def insertion_sort(lst):
    for i in range(1, len(lst)):
        key = lst[i]   
        j = i - 1  
        while j >= 0 and key < lst[j]:
            lst[j + 1] = lst[j]
            j = j - 1
        lst[j + 1] = key

def insertion_sort(lst, interval):
        for i in range(interval, len(lst)):
            key = lst[i]            
            j = i - interval          
            while j >= 0 and key < lst[j]:
                lst[j + interval] = lst[j]
                j = j - interval    
            lst[j + interval] = key
